<script setup>
import { ref, computed, onMounted, nextTick } from 'vue'
import { api, post, money } from './api'

const tab = ref('shop'), user = ref(null), products = ref([]), cart = ref([]), orders = ref([])
const error = ref(''), notice = ref(''), busy = ref(false), demo = ref(false)
const login = ref({ username: 'demo', password: '' }), loginOpen = ref(false)
const category = ref('全部'), search = ref(''), address = ref('上海市浦东新区世纪大道 100 号')
const chat = ref([]), message = ref(''), focused = ref(null), chatBusy = ref(false), thread = ref(null)
const adminTab = ref('refunds'), refunds = ref([]), adminOrders = ref([]), documents = ref([]), allProducts = ref([])
const doc = ref({ title: '', content: '' }), edit = ref(null)
let checkoutKey = crypto.randomUUID()
function resetCheckoutKey() { checkoutKey = crypto.randomUUID() }
const filtered = computed(() => products.value.filter(p => (category.value === '全部' || p.category === category.value) && (p.title + p.description).includes(search.value)))
const total = computed(() => cart.value.reduce((sum, p) => sum + Number(p.price) * p.quantity, 0))
const count = computed(() => cart.value.reduce((sum, p) => sum + p.quantity, 0))
const navigation = computed(() => [{ id: 'shop', title: '精选好物', icon: '◇' }, { id: 'cart', title: '购物车', icon: '▱' }, { id: 'orders', title: '我的订单', icon: '▤' }, { id: 'assistant', title: '服务助手', icon: '✳' }, ...(user.value?.role === 'ADMIN' ? [{ id: 'admin', title: '运营工作台', icon: '▦' }] : [])])
const title = computed(() => navigation.value.find(n => n.id === tab.value)?.title || '精选好物')
async function action(fn) { error.value = ''; notice.value = ''; busy.value = true; try { return await fn() } catch (e) { error.value = e.message } finally { busy.value = false } }
async function refresh() { products.value = await api('/products'); if (user.value) { [cart.value, orders.value] = await Promise.all([api('/cart'), api('/orders')]) } }
async function signIn() { await action(async () => { const result = await post('/auth/login', login.value); sessionStorage.setItem('zhifu-token', result.token); user.value = result.user; loginOpen.value = false; chat.value = []; focused.value = null; await refresh(); chat.value = await api('/assistant/history'); if(user.value.role==='ADMIN') await loadAdmin() }) }
async function signOut() { await action(async () => { await post('/auth/logout', {}); sessionStorage.removeItem('zhifu-token'); user.value = null; cart.value = []; orders.value = []; chat.value = []; focused.value = null; tab.value = 'shop' }) }
function requireLogin() { if (!user.value) { loginOpen.value = true; return false } return true }
async function navigate(id) { if (id !== 'shop' && !requireLogin()) return; tab.value = id; if(id==='admin') await action(loadAdmin) }
async function setQuantity(p, quantity) { if (!requireLogin()) return; await action(async () => { cart.value = await api('/cart/' + p.id, { method: 'PUT', body: JSON.stringify({ quantity }) }); checkoutKey = crypto.randomUUID(); notice.value = quantity ? '购物车已更新' : '商品已移出购物车' }) }
async function add(p) { const found = cart.value.find(c => c.id === p.id); await setQuantity(p, (found?.quantity || 0) + 1) }
async function checkout() { await action(async () => { const order = await post('/orders', { address: address.value }, { 'Idempotency-Key': checkoutKey }); checkoutKey = crypto.randomUUID(); await refresh(); tab.value = 'orders'; notice.value = '订单 ' + order.id + ' 已创建，请完成演示支付。' }) }
async function orderAction(order, type) { await action(async () => { await post('/orders/' + order.id + '/' + type, {}); await refresh(); notice.value = type === 'demo-pay' ? '演示支付成功，未扣除真实资金。' : '订单已取消，库存已恢复。' }) }
async function consult(object, type, text) { if(!requireLogin()) return; focused.value = { type, id: String(object.id), title: object.title || object.id }; tab.value = 'assistant'; if(text) await send(text) }
async function send(text = message.value) { if(!text.trim() || chatBusy.value || !requireLogin())return; const requestId = crypto.randomUUID(); error.value = ''; chatBusy.value = true; chat.value.push({ role: 'user', text }); message.value = ''; try { const result = await post('/assistant/chat', { text, request_id: requestId, object: focused.value ? { type: focused.value.type, id: focused.value.id } : null }); chat.value.push({ role: 'assistant', ...result }); await refresh() } catch(e) { error.value = e.message; chat.value.push({ role: 'assistant', text: '本次请求失败：' + e.message }) } finally { chatBusy.value = false; await nextTick(); thread.value?.scrollTo({ top: thread.value.scrollHeight, behavior: 'smooth' }) } }
async function loadAdmin() { [refunds.value, adminOrders.value, documents.value, allProducts.value] = await Promise.all([api('/admin/refunds'), api('/admin/orders'), api('/admin/knowledge'), api('/admin/products')]) }
async function review(r, approve) { await action(async () => { await post('/admin/refunds/' + r.id + '/review', { approve, note: approve ? '符合未发货退款条件' : '审核未通过，请联系人工客服' }); await loadAdmin(); await refresh(); notice.value = approve ? '申请已审核通过，订单和库存已更新。' : '申请已拒绝。' }) }
async function ship(o) { await action(async () => { await post('/admin/orders/' + o.id + '/ship', {}); await loadAdmin(); notice.value = '订单已标记为发货，物流为演示数据。' }) }
async function addDocument() { await action(async () => { await post('/admin/knowledge', doc.value); doc.value = { title: '', content: '' }; await loadAdmin(); notice.value = '文档已入库，可以在助手中检索。' }) }
async function removeDocument(d) { if(!window.confirm('删除知识文档“' + d.title + '”？'))return; await action(async () => { await api('/admin/knowledge/' + d.id, { method: 'DELETE' }); await loadAdmin() }) }
async function readFile(event) { const file = event.target.files?.[0]; if(!file)return; if(file.size>100000){error.value='文档不能超过 100KB';return} doc.value = { title: file.name.replace(/\.[^.]+$/, ''), content: await file.text() } }
async function saveProduct() { await action(async () => { const p = edit.value; await api('/admin/products/' + p.id, { method: 'PUT', body: JSON.stringify(p) }); edit.value = null; await refresh(); await loadAdmin(); notice.value = '商品已保存。' }) }
onMounted(async () => { await action(async () => { demo.value = (await api('/health')).demo; if(sessionStorage.getItem('zhifu-token')) { try { user.value = await api('/me') } catch { user.value = null } } await refresh(); if(user.value)chat.value = await api('/assistant/history') }) })
</script>

<template>
  <div class="layout">
    <aside class="sidebar">
      <a class="brand" @click="navigate('shop')"><span class="brand-symbol">甄</span><div>Curated Care<small>CURATED · CONNECTED</small></div></a>
      <div class="nav-label">发现与服务</div>
      <nav><button v-for="n in navigation" :key="n.id" :class="{active:tab===n.id}" @click="navigate(n.id)"><span>{{n.icon}}</span>{{n.title}}<b v-if="n.id==='cart' && count">{{count}}</b></button></nav>
      <div class="side-card"><span>✳</span><strong>每件好物，都有好服务</strong><p>商品咨询、订单查询与售后办理，在同一个地方完成。</p><button @click="navigate('assistant')">与助手聊聊 →</button></div>
      <div class="account"><span class="avatar">{{user?.username?.[0]?.toUpperCase() || '访'}}</span><div><strong>{{user?.username || '欢迎来访'}}</strong><small>{{user?.role==='ADMIN'?'运营管理员':user?'已登录':'登录后查看订单与服务'}}</small></div><button @click="user?signOut():loginOpen=true">{{user?'退出':'登录'}}</button></div>
    </aside>
    <main>
      <header><div><small>CURATED CARE / {{tab.toUpperCase()}}</small><h1>{{title}}</h1></div><span class="status"><i></i>服务相伴</span></header>
      <div v-if="demo" class="demo-bar">演示商城 · 支付与物流均为演示，不扣真实资金。</div>
      <div v-if="error" class="alert error" role="alert">{{error}}<button @click="error=''">×</button></div>
      <div v-if="notice" class="alert success" role="status">{{notice}}<button @click="notice=''">×</button></div>
      <section v-if="tab==='shop'">
        <div class="hero"><div><span class="eyebrow">GOOD FINDS, BETTER SERVICE</span><h2>认真挑选，<br>安心相伴。</h2><p>从挑选到售后，让每一次购物都更从容。</p><button @click="navigate('assistant')">认识你的服务助手 ↗</button></div><div class="hero-art"><div class="orbit"></div><span class="hero-mark">◇</span><small>SELECTED FOR EVERYDAY</small></div></div>
        <div class="toolbar"><div class="pills"><button v-for="c in ['全部','数码','生活']" :class="{selected:category===c}" @click="category=c">{{c}}</button></div><input v-model="search" aria-label="搜索商品" placeholder="搜索你想要的好物…"></div>
        <div class="product-grid"><article v-for="p in filtered" :key="p.id" class="product-card"><div class="product-art" :class="'art-'+p.id"><span>{{p.category==='数码'?'◉':p.title.includes('背包')?'▱':'◒'}}</span><small>{{p.category}}</small></div><div class="product-info"><h3>{{p.title}}</h3><p>{{p.description}}</p><div class="price">¥{{money(p.price)}}<small>库存 {{p.stock}}</small></div><div class="card-actions"><button class="primary" :disabled="busy || !p.stock" @click="add(p)">{{p.stock?'加入购物车':'暂时售罄'}}</button><button @click="consult(p,'product','介绍一下这件商品的使用和保养方法')">咨询助手</button></div></div></article></div><p v-if="!filtered.length" class="empty">没有找到商品，请换个关键词。</p>
      </section>
      <section v-if="tab==='cart'" class="panel"><h2>让好物来到身边</h2><div v-if="!cart.length" class="empty">购物车还是空的。<button @click="tab='shop'">去挑选好物</button></div><div v-for="p in cart" class="line-item"><div><h3>{{p.title}}</h3><small>¥{{money(p.price)}} / 件</small></div><div class="quantity"><button :disabled="busy" @click="setQuantity(p,p.quantity-1)">−</button><span>{{p.quantity}}</span><button :disabled="busy" @click="setQuantity(p,p.quantity+1)">+</button></div><strong>¥{{money(p.price*p.quantity)}}</strong></div><div v-if="cart.length" class="checkout"><label>收货地址<input v-model="address" maxlength="300" @input="resetCheckoutKey"></label><div><small>共 {{count}} 件商品</small><strong>¥{{money(total)}}</strong><button class="primary" :disabled="busy" @click="checkout">提交订单 →</button></div></div></section>
      <section v-if="tab==='orders'"><div v-if="!orders.length" class="panel empty">还没有订单，去挑选喜欢的商品吧。</div><article v-for="o in orders" class="panel order"><div class="order-heading"><span>{{o.id}}</span><b class="badge">{{o.status_desc}}</b></div><div v-for="p in o.items" class="line-item"><h3>{{p.title}} <small>× {{p.quantity}}</small></h3><strong>¥{{money(p.price*p.quantity)}}</strong></div><p class="muted">收货地址：{{o.address}}</p><p v-for="r in o.refunds" class="muted">退款申请：{{r.status}} · {{r.reason}}</p><div class="order-footer"><strong>合计 ¥{{money(o.amount)}}</strong><div><button v-if="o.status==='PENDING' && demo" class="primary" :disabled="busy" @click="orderAction(o,'demo-pay')">演示支付</button><button v-if="o.status==='PENDING'" :disabled="busy" @click="orderAction(o,'cancel')">取消订单</button><button @click="consult(o,'order','查询订单状态')">查订单</button><button @click="consult(o,'order','查询物流')">查物流</button><button v-if="o.status==='PAID' && !o.refunds.length" @click="consult(o,'order','我要申请退款')">申请退款</button></div></div></article></section>
      <section v-if="tab==='assistant'" class="assistant-layout"><div class="chat-panel"><div class="chat-heading"><span class="assistant-icon">✳</span><div><h3>甄选服务助手</h3><small>了解商品，也帮你处理售后</small></div></div><div ref="thread" class="thread"><div v-if="!chat.length" class="welcome"><span>✳</span><h2>今天，有什么可以帮你？</h2><p>咨询商品、了解政策，或选一张订单卡片开始办理。</p><div><button @click="send('退款政策是什么？')">了解退款政策</button><button @click="send('查询我的订单')">查看我的订单</button></div></div><article v-for="(m,index) in chat" :key="index" class="bubble" :class="m.role"><small>{{m.role==='user'?'你':'甄选服务助手'}}</small><p>{{m.text}}</p><details v-if="m.sources?.length"><summary>查看参考资料 · {{m.sources.length}} 条</summary><div v-for="(s,i) in m.sources"><strong>[{{i+1}}] {{s.title}}</strong><p>{{s.content}}</p></div></details></article><div v-if="chatBusy" class="thinking">正在查看资料与业务信息…</div></div><div v-if="focused" class="focus-tag">当前对象：{{focused.title}}<button @click="focused=null">×</button></div><form class="composer" @submit.prevent="send()"><input v-model="message" maxlength="2000" placeholder="说说你的问题…" aria-label="消息"><button class="primary" :disabled="chatBusy || !message.trim()">发送 ↑</button></form><div class="chat-hint">提交退款前会请你确认，申请结果以业务系统为准。</div></div><aside class="context-panel"><h3>选择咨询对象</h3><p>点击卡片，将订单或商品带入对话。</p><h4>最近订单</h4><button v-for="o in orders.slice(0,5)" class="object-card" @click="consult(o,'order')"><b>{{o.items[0]?.title}}</b><small>{{o.id}}</small><span>{{o.status_desc}} · ¥{{money(o.amount)}}</span></button><p v-if="!orders.length" class="muted">暂无订单</p><h4>商品</h4><button v-for="p in products" class="object-card" @click="consult(p,'product')"><b>{{p.title}}</b><span>¥{{money(p.price)}}</span></button></aside></section>
      <section v-if="tab==='admin'" class="panel"><div class="pills"><button v-for="[id,label] in [['refunds','退款审核'],['orders','订单发货'],['products','商品管理'],['knowledge','知识文档']]" :class="{selected:adminTab===id}" @click="adminTab=id">{{label}}</button></div><template v-if="adminTab==='refunds'"><div v-for="r in refunds" class="line-item"><div><h3>{{r.order_id}}</h3><p>{{r.reason}} · ¥{{money(r.amount)}} · {{r.status}}</p></div><div v-if="r.status==='PENDING'"><button class="primary" :disabled="busy" @click="review(r,true)">通过</button><button :disabled="busy" @click="review(r,false)">拒绝</button></div></div><p v-if="!refunds.length" class="empty">暂无退款申请。</p></template><template v-if="adminTab==='orders'"><div v-for="o in adminOrders" class="line-item"><div><h3>{{o.id}}</h3><p>{{o.status_desc}} · ¥{{money(o.amount)}}</p></div><button v-if="o.status==='PAID'" :disabled="busy" @click="ship(o)">标记发货</button></div></template><template v-if="adminTab==='products'"><button @click="edit={id:Date.now(),title:'',category:'生活',description:'',price:0,stock:0,active:true}">新增商品</button><div v-for="p in allProducts" class="line-item"><div><h3>{{p.title}}</h3><p>¥{{money(p.price)}} · 库存 {{p.stock}} · {{p.active?'上架':'下架'}}</p></div><button @click="edit={...p}">编辑</button></div></template><template v-if="adminTab==='knowledge'"><form class="document-form" @submit.prevent="addDocument"><h3>添加知识文档</h3><input v-model="doc.title" required maxlength="200" placeholder="文档标题"><textarea v-model="doc.content" required minlength="10" maxlength="100000" rows="7" placeholder="粘贴商品说明或售后政策，支持 Markdown"></textarea><div><input type="file" accept=".md,.txt" @change="readFile"><button class="primary" :disabled="busy">导入文档</button></div></form><div v-for="d in documents" class="line-item"><div><h3>{{d.title}}</h3><small>{{d.chunks}} 个知识片段</small></div><button :disabled="busy" @click="removeDocument(d)">删除</button></div></template></section>
      <footer>Curated Care · 让好物与好服务相遇</footer>
    </main>
    <div v-if="loginOpen" class="modal-overlay" @click.self="loginOpen=false"><form class="modal" @submit.prevent="signIn"><button type="button" class="close" @click="loginOpen=false">×</button><span class="eyebrow">WELCOME BACK</span><h2>欢迎来到Curated Care</h2><label>用户名<input v-model="login.username" autocomplete="username" required></label><label>密码<input v-model="login.password" type="password" autocomplete="current-password" required></label><p v-if="demo" class="muted">演示用户 demo / Demo12345!<br>管理员 admin / Admin12345!</p><p v-if="error" class="error-text">{{error}}</p><button class="primary" :disabled="busy">登录 →</button></form></div>
    <div v-if="edit" class="modal-overlay" @click.self="edit=null"><form class="modal" @submit.prevent="saveProduct"><button type="button" class="close" @click="edit=null">×</button><h2>商品资料</h2><label>名称<input v-model="edit.title" required maxlength="200"></label><label>分类<input v-model="edit.category" required maxlength="80"></label><label>说明<textarea v-model="edit.description" required maxlength="2000"></textarea></label><label>价格<input v-model.number="edit.price" type="number" min="0" max="999999.99" step="0.01" required></label><label>库存<input v-model.number="edit.stock" type="number" min="0" max="1000000" required></label><label class="checkbox"><input v-model="edit.active" type="checkbox">上架</label><button class="primary" :disabled="busy">保存</button></form></div>
  </div>
</template>
